    </div>","sections":[{"label":"","columns":[{"label":"","fields":[{"label":"Custom HTML","fieldname":"custom_html","fieldtype":"HTML","html":"<div style="font-size: 10px;">
<!-- Supplier & Billing Details Section -->
<div class="content">
    <div style="width: 100%; border: 1px solid black; border-collapse: collapse; font-size: 10px; page-break-inside: avoid; border-radius: 10px; overflow: hidden;">

        {% set supplier_address = frappe.db.get_value('Address', doc.supplier_address, ['address_line1', 'city', 'state', 'country', 'email_id', 'gstin', 'phone'], as_dict=True) or {} %}
        {% set billing_address = frappe.db.get_value('Address', doc.billing_address, ['address_line1', 'city', 'state', 'country', 'email_id', 'gstin', 'phone'], as_dict=True) or {} %}
        {% set is_intrastate = supplier_address.get("state") == billing_address.get("state") %}


        <!-- Supplier & Billing Titles -->
        <div style="display: flex; background: #f2f2f2;border-bottom: 1px solid black;">
            <div style="font-weight: bold; font-size: 12px;width: 50%;border-right: 1px solid black;height:45px;padding:10px;">&nbsp;&nbsp;Supplier Details</div>
            <div style="font-weight: bold; font-size: 12px;width: 50%;padding:10px;">&nbsp;&nbsp;Billing Details</div>
        </div>

        <!-- Supplier & Billing Information -->
        <div style="display: flex;">

            <!-- Supplier Details -->
            <div style="width: 50%; padding: 8px; border-right: 1px solid black; border-bottom: 1px solid black; box-sizing: border-box;">
                <div><strong>Name:</strong> {{ doc.supplier_address or "N/A" }}</div>
                <div><strong>Address:</strong> {{ supplier_address.get('address_line1', 'N/A') }}, {{ supplier_address.get('city', 'N/A') }}, {{ supplier_address.get('country', 'N/A') }}</div>
                <div><strong>Email:</strong> {{ supplier_address.get('email_id', 'N/A') }}</div>
                <div><strong>GSTIN:</strong> {{ supplier_address.get('gstin', 'N/A') }}</div>
                <div><strong>Contact:</strong> {{ supplier_address.get('phone', 'N/A') }}</div>
            </div>

            <!-- Billing Details -->
            <div style="width: 50%; padding: 8px; border-bottom: 1px solid black; box-sizing: border-box;">
                <div><strong>Name:</strong> {{ doc.billing_address or "N/A" }}</div>
                <div><strong>Address:</strong> {{ billing_address.get('address_line1', 'N/A') }}, {{ billing_address.get('city', 'N/A') }}, {{ billing_address.get('country', 'N/A') }}</div>
                <div><strong>Email:</strong> {{ billing_address.get('email_id', 'N/A') }}</div>
                <div><strong>GSTIN:</strong> {{ billing_address.get('gstin', 'N/A') }}</div>
                <div><strong>Contact:</strong> {{ billing_address.get('phone', 'N/A') }}</div>
            </div>
        </div>
    </div>
</div>


<br>
{% if doc.custom_subject %}
    <p style="font-size: 10px;"><strong>Subject:-  {{ doc.custom_subject }}</strong></p>
{% endif %}
{% if doc.amended_from %}
    <p style="font-size: 10px;"><strong>Amended Remarks:- {{doc.custom_remarks_amended}}</strong></p>
{% endif %}
{% if doc.custom_remarks %}
    <p style="font-size: 10px;">{{ doc.custom_remarks }}</p>
{% endif %}
<br>


<TABLE border=1 class='table' style="width: 100%; border: 1px solid black; border-radius: 10px; border-collapse: collapse; font-size: 10px;">
    <THEAD>
        <TR style="background-color: #f2f2f2; border: 1px solid black;">
            <TH style="text-align:center; width: 5%; font-weight: bold; color: black; border: 1px solid black; padding: 5px;">Sr</TH>
            <TH style="text-align:center; width: 30%; font-weight: bold; color: black; border: 1px solid black; padding: 5px;">Item & Description</TH>
            <TH style="text-align:center; width: 10%; font-weight: bold; color: black; border: 1px solid black; padding: 5px;">HSN Code</TH>
            <TH style="text-align:center; width: 7%; font-weight: bold; color: black; border: 1px solid black; padding: 5px;">UOM</TH>
            <TH style="text-align:center; width: 7%; font-weight: bold; color: black; border: 1px solid black; padding: 5px;">GST</TH>
            <TH style="text-align:center; width: 7%; font-weight: bold; color: black; border: 1px solid black; padding: 5px;">QTY</TH>
            <TH style="text-align:center; width: 15%; font-weight: bold; color: black; border: 1px solid black; padding: 5px;">Rate</TH>
            <TH style="text-align:center; width: 15%; font-weight: bold; color: black; border: 1px solid black; padding: 5px;">Amount</TH>
        </TR>
    </THEAD>
 <TBODY>
    {# Prepare GST rate grouping once #}
    {% set gst_rates_map = {} %}
    {% for item in doc.items %}
        {% set tax_template = frappe.get_doc("Item Tax Template", item.item_tax_template) if item.item_tax_template else None %}
        {% set gst_rate_key = (tax_template.gst_rate|int|string + "%") if tax_template else "N/A" %}
        {% set taxable_amount = item.net_amount|float %}
        {% set _ = gst_rates_map.update({gst_rate_key: gst_rates_map.get(gst_rate_key, 0) + taxable_amount}) %}
    {% endfor %}

    {# Render item rows #}
    {% for item in doc.items %}
        {% set tax_template = frappe.get_doc("Item Tax Template", item.item_tax_template) if item.item_tax_template else None %}
        {% set gst_rate_display = (tax_template.gst_rate|int|string + "%") if tax_template else "N/A" %}
        <TR style="border: 1px solid black; height: auto;">
            <TD style="border: 1px solid black; text-align:center; padding: 5px;">{{ loop.index }}</TD>
            <TD style="border: 1px solid black; padding: 5px;">
                <strong>{{ item.item_name }}</strong><br>
                <span style="font-size: 9px; color: gray;">{{ item.description or "-" }}</span>
            </TD>
            <TD style="border: 1px solid black; text-align:center; padding: 5px;">{{ item.gst_hsn_code or "-" }}</TD>
            <TD style="border: 1px solid black; text-align:center; padding: 5px;">{{ item.get_formatted("uom", 0) }}</TD>
            <TD style="border: 1px solid black; text-align:center; padding: 5px;">{{ gst_rate_display }}</TD>
            <TD style="border: 1px solid black; text-align:center; padding: 5px;">{{ item.get_formatted("qty", 0) }}</TD>
            <TD style="border: 1px solid black; text-align:right; padding: 5px;">
                {{ frappe.utils.fmt_money('%0.2f'|format(item.net_rate|float|abs), currency='') }}
            </TD>
            <TD style="border: 1px solid black; text-align:right; padding: 5px;">
                {{ frappe.utils.fmt_money('%0.2f'|format(item.net_amount|float|abs), currency='') }}
            </TD>
        </TR>
    {% endfor %}

    {# Calculate tax totals and rates #}
    {% set cgst_tax = doc.taxes | selectattr("account_head", "equalto", "Input Tax CGST - S") | list %}
    {% set sgst_tax = doc.taxes | selectattr("account_head", "equalto", "Input Tax SGST - S") | list %}
    {% set igst_tax = doc.taxes | selectattr("account_head", "equalto", "Input Tax IGST - S") | list %}

    {% set cgst_amount = cgst_tax | map(attribute="tax_amount") | sum %}
    {% set sgst_amount = sgst_tax | map(attribute="tax_amount") | sum %}
    {% set igst_amount = igst_tax | map(attribute="tax_amount") | sum %}

    {% set cgst_rate = cgst_tax | map(attribute="rate") | sum %}
    {% set sgst_rate = sgst_tax | map(attribute="rate") | sum %}
    {% set igst_rate = igst_tax | map(attribute="rate") | sum %}

    {% set use_igst = igst_amount > 0 %}
    {% set rowspan_value = 3 if use_igst else 4 %}

    {# Summary rows #}
    <TR style="border: 1px solid black;">
        <TD colspan="6" rowspan="{{ rowspan_value }}" 
            style="border: 1px solid black; text-align:left; padding: 5px; font-weight: bold;">
            {{ frappe.utils.money_in_words(doc.grand_total) }}
        </TD>
        <TD style="border: 1px solid black; text-align:right; padding: 5px; font-weight: bold;">Sub Total</TD>
        <TD style="border: 1px solid black; text-align:right; padding: 5px;">
            {{ frappe.utils.fmt_money(doc.net_total, currency='') }}
        </TD>
    </TR>

    {% if use_igst %}
        <TR>
            <TD style="border: 1px solid black; text-align:right; padding: 5px; font-weight: bold;">
                IGST @ {{ '%.2f'|format(igst_rate) }}%
            </TD>
            <TD style="border: 1px solid black; text-align:right; padding: 5px;">
                {{ frappe.utils.fmt_money(igst_amount, currency='') }}
            </TD>
        </TR>
    {% else %}
        <TR>
            <TD style="border: 1px solid black; text-align:right; padding: 5px; font-weight: bold;">
                CGST @ {{ '%.2f'|format(cgst_rate) }}%
            </TD>
            <TD style="border: 1px solid black; text-align:right; padding: 5px;">
                {{ frappe.utils.fmt_money(cgst_amount, currency='') }}
            </TD>
        </TR>
        <TR>
            <TD style="border: 1px solid black; text-align:right; padding: 5px; font-weight: bold;">
                SGST @ {{ '%.2f'|format(sgst_rate) }}%
            </TD>
            <TD style="border: 1px solid black; text-align:right; padding: 5px;">
                {{ frappe.utils.fmt_money(sgst_amount, currency='') }}
            </TD>
        </TR>
    {% endif %}

    <TR>
        <TD style="border: 1px solid black; text-align:right; padding: 5px; font-weight: bold;">Grand Total</TD>
        <TD style="border: 1px solid black; text-align:right; padding: 5px;">
            {{ frappe.utils.fmt_money(doc.grand_total, currency='') }}
        </TD>
    </TR>

 <!-- Header Row 1 -->
<tr>
    <th colspan="3" style="border: 1px solid black; padding: 5px;">GST Rate</th>
    <th colspan="3" style="border: 1px solid black; padding: 5px; text-align: right;">Taxable Value</th>

    {% if use_igst %}
        <th style="border: 1px solid black; padding: 5px; text-align: right;">IGST Rate</th>
        <th style="border: 1px solid black; padding: 5px; text-align: right;">IGST Amount</th>
    {% else %}
        <th style="border: 1px solid black; padding: 5px; text-align: right;">
            CGST<br><span style="font-size: 9px; font-weight: normal;">Rate / Amount</span>
        </th>
        <th style="border: 1px solid black; padding: 5px; text-align: right;">
            SGST<br><span style="font-size: 9px; font-weight: normal;">Rate / Amount</span>
        </th>
    {% endif %}
</tr>


{% for gst_rate, taxable_amount in gst_rates_map.items() %}
    {% if gst_rate != "N/A" and taxable_amount > 0 %}
        {% set numeric_rate = gst_rate.replace('%', '') | float %}
        <tr>
            <td colspan="3" style="border: 1px solid black; padding: 5px;">{{ gst_rate }}</td>
            <td colspan="3" style="border: 1px solid black; text-align: right; padding: 5px;">
                {{ frappe.utils.fmt_money(taxable_amount, currency='') }}
            </td>

            {% if use_igst %}
                <td style="border: 1px solid black; text-align: right; padding: 5px;">
                    {{ '%.2f'|format(numeric_rate) }}%
                </td>
                <td style="border: 1px solid black; text-align: right; padding: 5px;">
                    {{ frappe.utils.fmt_money((taxable_amount * numeric_rate / 100), currency='') }}
                </td>
            {% else %}
                {% set half_rate = numeric_rate / 2 %}
                <td style="border: 1px solid black; text-align: right; padding: 5px;">
                    {{ '%.2f'|format(half_rate) }}%<br>
                    {{ frappe.utils.fmt_money((taxable_amount * half_rate / 100), currency='') }}
                </td>
                <td style="border: 1px solid black; text-align: right; padding: 5px;">
                    {{ '%.2f'|format(half_rate) }}%<br>
                    {{ frappe.utils.fmt_money((taxable_amount * half_rate / 100), currency='') }}
                </td>
            {% endif %}
        </tr>
    {% endif %}
{% endfor %}

</TBODY>


</TABLE>
 {% set terms = doc.custom_terms_table | selectattr("show_tc", "equalto", 1) | sort(attribute="sequence") %}

{% if terms %}
    <h3 style="font-size: 12px;">Commercial Terms & Conditions</h3>
    <table style="width: 100%; border-collapse: collapse; font-size: 10px;">
        {% for term in terms %}
            <tr>
                <td style="width: 20%; font-weight: bold; vertical-align: top; padding: 5px;">{{ loop.index }}. {{ term.title }}</td>
                <td style="width: 80%; padding: 5px;">{{ term.terms }}</td>
            </tr>
        {% endfor %}
    </table>
{% endif %}


{% set cfo_sign = frappe.db.get_single_value('Digital Signature', 'cfo') %}
{% set purchase_manager = frappe.db.get_single_value('Digital Signature', 'purchase_manager') %}

{% set purchase_users = frappe.db.get_all("Users and Signature", 
    filters={"parent": "Digital Signature"}, 
    fields=["purchase_user_name", "user_signature"]
) %}

{% set purchase_sign = purchase_users | selectattr("purchase_user_name", "equalto", frappe.session.user) | map(attribute="user_signature") | list %}
<br>
<h3 style="font-size: 12px;">Authorized Signatures</h3>
<table style="width: 100%; border-collapse: collapse; border: 1px solid black; text-align: center; font-size: 10px;">
    <tr>
        <th style="border: 1px solid black; padding: 10px;">Purchase Department</th>
        <th style="border: 1px solid black; padding: 10px;">Purchase Manager</th>
        <th style="border: 1px solid black; padding: 10px;">CFO</th>
        <th style="border: 1px solid black; padding: 10px;">Vendor Acceptance</th>
    </tr>
    <tr>
        <td style="border: 1px solid black; padding: 20px; font-style: italic;">
            {% if doc.custom_sahayog_status in ["Pending From Purchase Manager", "Pending From CFO", "Approved"] and purchase_sign %}
                <img src="{{ purchase_sign[0] }}" alt="Purchase Department Signature" style="max-width: 100px; height: auto;">
            {% else %}
                ____________
            {% endif %}
        </td>
        <td style="border: 1px solid black; padding: 20px;">
            {% if doc.custom_sahayog_status in ["Pending From CFO", "Approved"] and purchase_manager %}
                <img src="{{ purchase_manager }}" alt="Purchase Manager Signature" style="max-width: 100px; height: auto;">
            {% else %}
                ____________
            {% endif %}
        </td>
        <td style="border: 1px solid black; padding: 20px;">
            {% if doc.custom_sahayog_status == "Approved" and cfo_sign %}
                <img src="{{ cfo_sign }}" alt="CFO Signature" style="max-width: 100px; height: auto;">
            {% else %}
                ____________
            {% endif %}
        </td>
        <td style="border: 1px solid black; padding: 10px;">
            <div style="font-weight: bold; padding-bottom: 15px;font-size:11px;">We accept for {{ doc.supplier }}</div>
            <div style="font-style: italic;">____________</div>
        </td>
    </tr>
</table>
</div>"}]}],"has_fields":true},{"label":"","columns":[{"label":"","fields":[]}]}]}
